package app.unifeed.auth;
import jakarta.servlet.ServletException; import jakarta.servlet.http.*; import java.io.IOException; import java.net.URLEncoder; import java.nio.charset.StandardCharsets; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.core.Authentication; import org.springframework.security.oauth2.core.user.OAuth2User; import org.springframework.security.web.authentication.AuthenticationSuccessHandler; import org.springframework.stereotype.Component;
@Component public class OAuthSuccessHandler implements AuthenticationSuccessHandler {private final AuthService auth;private final String redirect;public OAuthSuccessHandler(AuthService a,@Value("${app.frontend.oauth-success-url:http://localhost:5173/auth/callback}")String r){auth=a;redirect=r;}public void onAuthenticationSuccess(HttpServletRequest request,HttpServletResponse response,Authentication authentication)throws IOException,ServletException{OAuth2User user=(OAuth2User)authentication.getPrincipal();AuthService.AuthTokens tokens=auth.oauthLogin(user.getAttribute("email"),user.getAttribute("name"));response.addHeader("Set-Cookie",tokens.refreshCookie());response.sendRedirect(redirect+"#access_token="+URLEncoder.encode(tokens.accessToken(),StandardCharsets.UTF_8));}}
